/**
 * src/agents/tx-7-imp-1/prompts/action-04.ts
 * 
 * Action 4: ボトルネック変化パターンを可視化レポートとして作成
 * 
 * tx-7-imp-1 Agent の Action 4 プロンプト生成モジュール
 * 月次レポート生成から分析完了までの自動実行フロー内で、
 * 抽出された課題データから時系列ボトルネック推移を分析し、
 * 可視化レポート形式で部長に提示するためのプロンプトを構築する
 */

export const ACTION_04_PROMPT_VERSION = "1.0.0";

export interface Action04PromptInput {
  /** 分析対象期間の開始日（YYYY-MM-DD形式） */
  analysisStartDate: string;
  /** 分析対象期間の終了日（YYYY-MM-DD形式） */
  analysisEndDate: string;
  /** 抽出済み課題データの配列 */
  extractedIssues: Array<{
    issueId: string;
    title: string;
    category: string;
    priority: "high" | "medium" | "low";
    reportedDate: string;
    resolvedDate?: string;
    affectedTeams: string[];
    description: string;
  }>;
  /** 過去の同一課題の再発パターン情報 */
  recurrencePatterns: Array<{
    issueCategory: string;
    occurrenceCount: number;
    lastOccurrenceDate: string;
    averageResolutionDays: number;
  }>;
  /** チーム別の課題発生件数 */
  teamIssueStats: Array<{
    teamName: string;
    totalIssues: number;
    highPriorityCount: number;
    averageResolutionDays: number;
  }>;
  /** 部長の名前 */
  managerName: string;
  /** 組織名 */
  organizationName: string;
}

export interface Action04PromptOutput {
  /** 生成されたプロンプト文字列 */
  prompt: string;
  /** プロンプトのメタデータ */
  metadata: {
    version: string;
    actionNumber: 4;
    purpose: string;
    targetAudience: string;
  };
}

/**
 * Action 4 プロンプトを構築する関数
 * 
 * 月次レポート生成フロー内で、抽出された課題データから
 * ボトルネック変化パターンを時系列で分析し、
 * 可視化レポート形式で提示するためのAIプロンプトを生成する
 * 
 * @param input - プロンプト生成に必要な入力データ
 * @returns 生成されたプロンプトとメタデータ
 */
export function buildAction04Prompt(input: Action04PromptInput): Action04PromptOutput {
  const {
    analysisStartDate,
    analysisEndDate,
    extractedIssues,
    recurrencePatterns,
    teamIssueStats,
    managerName,
    organizationName,
  } = input;

  // 課題をカテゴリ別に集計
  const categoryStats = new Map<string, { count: number; highPriority: number }>();
  extractedIssues.forEach((issue) => {
    const current = categoryStats.get(issue.category) || { count: 0, highPriority: 0 };
    current.count += 1;
    if (issue.priority === "high") {
      current.highPriority += 1;
    }
    categoryStats.set(issue.category, current);
  });

  // 日付ごとの課題発生数を集計
  const dailyIssueCount = new Map<string, number>();
  extractedIssues.forEach((issue) => {
    const date = issue.reportedDate.split("T")[0];
    dailyIssueCount.set(date, (dailyIssueCount.get(date) || 0) + 1);
  });

  // 優先度別の課題数
  const priorityStats = {
    high: extractedIssues.filter((i) => i.priority === "high").length,
    medium: extractedIssues.filter((i) => i.priority === "medium").length,
    low: extractedIssues.filter((i) => i.priority === "low").length,
  };

  // 再発リスクが高いカテゴリを特定
  const highRiskCategories = recurrencePatterns
    .filter((p) => p.occurrenceCount >= 3)
    .sort((a, b) => b.occurrenceCount - a.occurrenceCount)
    .slice(0, 5);

  // 最も課題が多いチーム
  const topTeams = teamIssueStats
    .sort((a, b) => b.totalIssues - a.totalIssues)
    .slice(0, 3);

  const prompt = `# 月次ボトルネック分析レポート生成タスク

## 実行コンテキスト
- 分析期間: ${analysisStartDate} ～ ${analysisEndDate}
- 対象組織: ${organizationName}
- 報告先: ${managerName}
- 総課題件数: ${extractedIssues.length}件

## 分析対象データ

### 課題の優先度分布
- 高優先度: ${priorityStats.high}件
- 中優先度: ${priorityStats.medium}件
- 低優先度: ${priorityStats.low}件

### カテゴリ別課題統計
${Array.from(categoryStats.entries())
  .map(
    ([category, stats]) =>
      `- ${category}: ${stats.count}件（高優先度: ${stats.highPriority}件）`
  )
  .join("\n")}

### 再発リスク分析（3回以上発生したカテゴリ）
${
  highRiskCategories.length > 0
    ? highRiskCategories
        .map(
          (p) =>
            `- ${p.issueCategory}: ${p.occurrenceCount}回発生、平均解決期間 ${p.averageResolutionDays}日`
        )
        .join("\n")
    : "- 再発リスク高のカテゴリなし"
}

### チーム別課題統計（上位3チーム）
${topTeams
  .map(
    (team) =>
      `- ${team.teamName}: 総課題 ${team.totalIssues}件、高優先度 ${team.highPriorityCount}件、平均解決期間 ${team.averageResolutionDays}日`
  )
  .join("\n")}

### 日別課題発生推移
${Array.from(dailyIssueCount.entries())
  .sort(([dateA], [dateB]) => dateA.localeCompare(dateB))
  .map(([date, count]) => `- ${date}: ${count}件`)
  .join("\n")}

## タスク指示

以下の要件に従い、可視化レポートを生成してください：

### 1. ボトルネック変化パターンの特定
- 分析期間内での課題発生パターンの時系列変化を分析
- 課題が増加傾向か減少傾向かを判定
- 特定の時期に課題が集中していないか確認

### 2. 再発パターンの可視化
- 同一カテゴリの課題が複数回発生している場合、その傾向を強調
- 再発リスク高のカテゴリについて、対応方針の改善を提案

### 3. チーム別パフォーマンス分析
- 課題発生件数が多いチームを特定
- 解決期間が長いチームを特定
- 改善が必要なチームに対する支援施策を提案

### 4. 優先度別の課題分布分析
- 高優先度課題の割合が高い場合、その原因を推測
- 優先度判定の妥当性を検証

### 5. レポート形式の要件
- 見出しは「## 」で始める
- 数値データは表形式またはリスト形式で提示
- グラフ説明は ASCII アート または テキスト記述で表現
- 各セクションに「改善提案」を含める

## 出力形式

以下の構成でレポートを生成してください：

\`\`\`
## 月次ボトルネック分析レポート

### 1. 分析期間サマリー
[期間内の課題発生状況の概要]

### 2. 時系列ボトルネック推移
[日別・週別の課題発生パターン分析]

### 3. 再発パターン分析
[同一課題の再発傾向と対応状況]

### 4. チーム別パフォーマンス
[チーム別の課題件数と解決期間]

### 5. 優先度別分析
[優先度分布と高優先度課題への対応状況]

### 6. 改善提案
[特定されたボトルネックに対する具体的な改善施策]

### 7. 次月への推奨アクション
[優先度付きの改善施策リスト]
\`\`\`

## 注意事項
- 分析結果は客観的なデータに基づいて記述
- 推測や仮説は「推定される」「考えられる」などの表現を使用
- 改善提案は実行可能で具体的な内容にする
- ${managerName}が朝会で説明しやすい表現を心がける`;

  return {
    prompt,
    metadata: {
      version: ACTION_04_PROMPT_VERSION,
      actionNumber: 4,
      purpose: "ボトルネック変化パターンを可視化レポートとして作成",
      targetAudience: "部長（朝会報告用）",
    },
  };
}
